function modal(kind,html){closeDropdown();if(battle?.menuOpen)battle.closeMenu();pausedBefore=battle?.paused||false;if(battle?.phase==='battle')battle.paused=true;modalKind=kind;$('modalContent').innerHTML=html;enhanceSelects($('modalContent'));$('modal').hidden=false}
function closeModal(){closeDropdown();if(modalKind==='result')return;$('modal').hidden=true;if(battle?.phase==='battle')battle.paused=pausedBefore;modalKind=''}$('closeModal').onclick=closeModal;
function help(){modal('help',`<div class="eyebrow">FIELD MANUAL</div><h2>모바일 전술 조작</h2><ul><li><b>터치</b>: 아군 선택. 빠르게 두 번 터치하면 화면 안의 같은 종류 전체 선택.</li><li><b>빈 땅을 길게 누르고 드래그</b>: 범위 선택. 하단 ‘범위’를 켜면 바로 드래그 선택.</li><li><b>스와이프</b>: 카메라 이동. 두 손가락 이동과 핀치 확대 지원.</li><li><b>명령</b>: 메뉴가 열리는 순간 0.5×. 지점·대상을 지정하거나 취소하면 1.0×.</li><li><b>Ctrl → 숫자</b>: 부대 지정. 숫자만 누르면 호출, 두 번 누르면 부대 위치로 이동.</li><li><b>생산</b>: 본진이나 생산 건물을 선택하고 하단 ‘생산 / 명령’을 누르세요.</li><li><b>건설</b>: 일꾼 선택 → 건설 / 명령 → 건물 → 지도에서 건설 위치 지정.</li><li><b>채취</b>: 일꾼 선택 후 미네랄 또는 완성된 가스 건물을 터치. 집결 지점을 자원에 지정할 수도 있습니다.</li><li><b>테크트리</b>: 완성된 선행 건물·부속 건물·전력·크립·연구 조건을 충족해야 다음 생산이 가능합니다.</li></ul><h3>PC 조작</h3><p>M·A·P: 이동·공격·패트롤 / H·S: 홀드·정지<br>숫자: 부대 호출 / Ctrl+숫자: 부대 지정<br>F2: 전체 선택 / Space: 일시 정지 / Esc: 취소</p><button class="primary" id="helpDone">확인</button>`);$('helpDone').onclick=closeModal}$('help').onclick=help;
function settingsModal(){modal('settings',`<div class="eyebrow">COMMAND CENTER</div><h2>설정</h2>${[['배경음악','bgm'],['효과음','sfx'],['유닛 음성','voice']].map(([label,key])=>`<label>${label}<input id="vol-${key}" type="range" min="0" max="1" step=".01" value="${settings[key]}"></label>`).join('')}<label>렌더링<select id="quality"><option value="auto" ${settings.quality==='auto'?'selected':''}>자동 · 선명하게</option><option value="low" ${settings.quality==='low'?'selected':''}>절전 · 낮은 해상도</option></select></label><div class="row"><button id="pause">${pausedBefore?'전투 재개':'일시 정지 유지'}</button><button id="manual">조작 방법</button><button id="leave">작전 나가기</button></div><p>미니스타 ${VERSION} · 리마스터 ${data.sourceBuild}<br>설정과 전투 기록은 기기에 저장됩니다.</p>`);for(const key of ['bgm','sfx','voice'])$('vol-'+key).oninput=e=>{settings[key]=Number(e.target.value);save('settings',settings);if(bgm)bgm.volume=settings.bgm;if(voice)voice.volume=settings.voice};$('quality').onchange=e=>{settings.quality=e.target.value;save('settings',settings);resize()};$('pause').onclick=()=>{pausedBefore=!pausedBefore;closeModal()};$('manual').onclick=()=>{const p=pausedBefore;help();pausedBefore=p};$('leave').onclick=()=>{modalKind='';$('modal').hidden=true;bgm?.pause();newBattle()}}$('settings').onclick=settingsModal;
function resultModal(r){modal('result',`<div class="eyebrow">OPERATION COMPLETE</div><h2 style="font-size:32px;color:${r.win?'#e4d28b':'#de987f'}">${r.win?'승리':'패배'}</h2><p>${r.reason}</p><div class="stats">${[['전투 시간',Math.floor(r.time/60)+':'+String(Math.floor(r.time%60)).padStart(2,'0')],['생산한 병력',r.produced+'기'],['생존 병력',r.survivors+'기'],['적 처치',r.kills+'기'],['아군 손실',r.losses+'기'],['총 피해량',Math.round(r.damage).toLocaleString()]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><button id="retry" class="primary">다시 출전하기</button><button id="toTitle" class="secondary">종족 선택으로</button>`);$('retry').onclick=()=>{modalKind='';$('modal').hidden=true;newBattle();battle.begin()};$('toTitle').onclick=()=>{modalKind='';$('modal').hidden=true;newBattle()}}
$('records').onclick=()=>{const records=read('records',[]);modal('records',`<div class="eyebrow">BATTLE LOG</div><h2>전투 기록</h2>${records.length?records.slice(0,20).map(r=>`<div class="log"><span>${r.win?'승리':'패배'} · ${labels[r.race]}<br><small>${new Date(r.date).toLocaleDateString('ko-KR')} · ${Math.floor(r.time/60)}분 ${Math.floor(r.time%60)}초</small></span><b>${r.kills} 처치</b></div>`).join(''):'<p>첫 작전에 출전해 기록을 남겨보세요.</p>'}`)};
function raceUI(){for(const el of document.querySelectorAll('[data-race]')){el.classList.toggle('active',el.dataset.race===race);el.setAttribute('aria-pressed',el.dataset.race===race)}$('raceBriefing').textContent={terran:'테란 원정대의 지휘권이 이양되었습니다.',zerg:'군단이 당신의 명령을 기다립니다.',protoss:'기사단이 당신의 지휘를 기다립니다.'}[race];$('gasIcon').src=iconResource({terran:1,zerg:2,protoss:3}[race]);$('supplyIcon').src=iconResource({terran:4,zerg:5,protoss:6}[race])}const iconResource=n=>'assets/icons/resource_'+String(n).padStart(3,'0')+'.png';for(const el of document.querySelectorAll('[data-race]'))el.onclick=()=>{race=el.dataset.race;save('race',race);raceUI()};$('deploy').onclick=()=>{newBattle();battle.begin()};
addEventListener('keydown',e=>{if(!battle)return;if(e.key==='Escape'){e.preventDefault();if(battle.menuOpen)battle.closeMenu();else if(!$('modal').hidden)closeModal();return}if(!$('modal').hidden||['title','result'].includes(battle.phase))return;if(e.key===' '){e.preventDefault();battle.paused=!battle.paused;toast(battle.paused?'일시 정지':'전투 재개');return}if(e.key==='F2'){e.preventDefault();$('selectAll').click();return}if(/^\d$/.test(e.key)){e.preventDefault();const i=e.key==='0'?9:Number(e.key)-1;if(e.ctrlKey||ctrl){if(battle.assignGroup(i))ctrl=false;groupsUI()}else battle.recallGroup(i);return}const key={m:'move',a:'attack',p:'patrol',h:'hold',s:'stop',b:'burrow'}[e.key.toLowerCase()];if(key&&battle.phase==='battle'&&battle.selected.length){e.preventDefault();if(!battle.menuOpen)openMenu();battle.chooseCommand(key)}});
document.addEventListener('visibilitychange',()=>{last=0;if(document.hidden)bgm?.pause();else if(battle?.phase==='battle')bgm?.play().catch(()=>{})});
// Remove only MiniStar's retired offline storage; keep settings and battle records.
async function retireOfflineStorage(){
 try{
  const scope=new URL('./',location.href).href;let retired=false;
  if('serviceWorker'in navigator){for(const registration of await navigator.serviceWorker.getRegistrations())if(registration.scope===scope)retired=(await registration.unregister())||retired}
  if('caches'in window)await Promise.all((await caches.keys()).filter(key=>key.startsWith('ministar-')).map(key=>caches.delete(key)));
  if(retired&&navigator.serviceWorker.controller){location.reload();return false}
 }catch(error){console.warn('Legacy game cache cleanup:',error)}
 return true;
}
async function boot(){try{if(!await retireOfflineStorage())return;enhanceSelects();data=await fetch('assets/data.json').then(r=>{if(!r.ok)throw Error('전투 데이터를 읽을 수 없습니다.');return r.json()});const extra=await fetch('rts-data.json?v=0.2.0').then(r=>{if(!r.ok)throw Error('생산 데이터를 읽을 수 없습니다.');return r.json()});Object.assign(data.units,extra.units);Object.assign(data.graphics,extra.graphics);for(const [key,spec]of Object.entries(extra.research))Object.assign(RESEARCH[key],spec);terrain=await loadImage('assets/terrain.webp');if(!terrain)throw Error('지형 이미지를 읽을 수 없습니다.');newBattle();raceUI();$('boot').hidden=true;requestAnimationFrame(render)}catch(e){$('bootText').textContent=e.message+' · start.sh로 서버를 실행한 뒤 접속하세요.';console.error(e)}}boot();
